from dataclasses import dataclass
from datetime import date
from typing import Optional

# PROVISIONAL policy: product has not decided how to handle expired promotions.
# Current choice: require explicit customer confirmation to proceed at full price.


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: int
    expires_on: date


@dataclass(frozen=True)
class CheckoutResult:
    status: str  # "placed" or "needs_confirmation"
    total_cents: int
    promotion_applied: bool
    message: Optional[str] = None


def checkout(subtotal_cents: int, promotion: Optional[Promotion], today: date,
             confirm_expired: bool = False) -> CheckoutResult:
    if promotion is None:
        return CheckoutResult("placed", subtotal_cents, False)
    if today <= promotion.expires_on:
        total = subtotal_cents * (100 - promotion.percent_off) // 100
        return CheckoutResult("placed", total, True)
    msg = f"Promotion {promotion.code} expired on {promotion.expires_on.isoformat()}."
    if confirm_expired:
        return CheckoutResult("placed", subtotal_cents, False, msg)
    return CheckoutResult("needs_confirmation", subtotal_cents, False, msg)
