import unittest
from datetime import date
from checkout import Promotion, checkout

PROMO = Promotion("SAVE10", 10, date(2026, 10, 30))


class CheckoutTests(unittest.TestCase):
    def test_no_promotion(self):
        r = checkout(1000, None, date(2026, 10, 31))
        self.assertEqual((r.status, r.total_cents), ("placed", 1000))

    def test_valid_promotion_applies(self):
        r = checkout(1000, PROMO, date(2026, 10, 29))
        self.assertEqual((r.status, r.total_cents, r.promotion_applied), ("placed", 900, True))

    def test_valid_on_expiry_day(self):
        self.assertTrue(checkout(1000, PROMO, date(2026, 10, 30)).promotion_applied)

    def test_expired_requires_confirmation(self):
        r = checkout(1000, PROMO, date(2026, 10, 31))
        self.assertEqual(r.status, "needs_confirmation")
        self.assertEqual(r.total_cents, 1000)
        self.assertFalse(r.promotion_applied)
        self.assertIn("SAVE10", r.message)

    def test_expired_confirmed_places_at_full_price(self):
        r = checkout(1000, PROMO, date(2026, 10, 31), confirm_expired=True)
        self.assertEqual((r.status, r.total_cents, r.promotion_applied), ("placed", 1000, False))


if __name__ == "__main__":
    unittest.main()
